const GUIDE={
 pt:{title:'Ligar o SAC a um site de jogos',intro:'Como um jogador do 7987.com ou do 8557.com chega até um agente aqui, e o que cada parte precisa fazer.',
  flow:['Jogador no 7987.com','Widget de chat','Servidor do SAC','Agente da linha 7987'],step:'Passo',who:'Quem faz',opt:'opcional',
  steps:[
   ['Colocar o SAC num servidor de verdade','Hoje ele roda só dentro do navegador. Para receber jogadores de um site, precisa estar hospedado num servidor com banco de dados e conexão em tempo real, num endereço próprio, como sac.example.com.','nós escrevemos o código do servidor; você contrata a hospedagem (VPS, Railway, Render…) e o domínio.'],
   ['Colocar o widget de chat no site','É o balão de atendimento no canto da tela. Um pequeno código vai no site; o data-linha diz de qual linha o jogador veio: 7987.com usa 7987, 8557.com usa 8557.','nós criamos o widget.'],
   ['Instalar o código no back office da plataforma','Plataformas de jogos costumam ter no painel administrativo um campo como “código de chat ao vivo”, “script personalizado” ou “integração de suporte”, o mesmo lugar onde se instala um LiveChat ou um Tawk.to. Cole o código ali.','você, se tiver acesso ao back office; senão, o operador ou a equipe técnica da plataforma.'],
   ['Identificar o jogador','Para o agente ver o ID, o nome ou o login do jogador, o site precisa enviar esses dados ao widget. Para consultar saldo, depósitos ou saques dentro do SAC, a plataforma precisa ter uma API e liberar o acesso.','a equipe técnica da plataforma.']],
  code:'Código de exemplo para cada site',copy:'Copiar',copied:'Copiado',codeNote:'sac.example.com é só um exemplo. O endereço real vem depois do passo 1.',
  st:'Onde estamos',ready:'Pronto',readyL:['Protótipo do SAC: logins, perfis, linhas 7987 e 8557','Distribuição automática, transferências, scripts, anexos'],
  we:'Nós fazemos a seguir',weL:['Servidor com banco de dados e chat em tempo real','Widget de chat para os dois sites'],
  you:'Depende de você',youL:['Hospedagem e domínio','Acesso ao back office do 7987.com e do 8557.com, ou contato com a equipe técnica deles'],
  simT:'Testar a simulação',simD:'Um site de jogos fictício com o balão de chat. Abra numa nova aba, escreva como jogador e responda no SAC.',simB:'Abrir site',
  ask:'Para continuar: veja se o painel administrativo do 7987.com e do 8557.com tem um campo para colar código de chat ao vivo ou script personalizado.'},
 vi:{tab:'Tiếng Việt',lang:'vi',title:'Kết nối hệ thống CSKH với trang game',intro:'Cách người chơi trên 7987.com hoặc 8557.com liên hệ với nhân viên tại đây, và việc mỗi bên cần làm.',
  flow:['Người chơi trên 7987.com','Widget chat','Máy chủ CSKH','Nhân viên line 7987'],step:'Bước',who:'Ai làm',opt:'tùy chọn',
  steps:[
   ['Đưa hệ thống CSKH lên máy chủ thật','Hiện tại hệ thống chỉ chạy trong trình duyệt. Để nhận người chơi từ một trang web, hệ thống cần được lưu trữ trên máy chủ có cơ sở dữ liệu và kết nối thời gian thực, với địa chỉ riêng như sac.example.com.','chúng tôi viết mã máy chủ; bạn thuê hosting (VPS, Railway, Render…) và tên miền.'],
   ['Thêm widget chat vào trang web','Đây là bong bóng chat ở góc màn hình. Một đoạn mã nhỏ được đặt vào trang; data-linha cho biết người chơi đến từ line nào: 7987.com dùng 7987, 8557.com dùng 8557.','chúng tôi tạo widget.'],
   ['Cài mã vào trang quản trị (back office) của nền tảng','Các nền tảng game thường có mục như “mã live chat”, “script tùy chỉnh” hoặc “tích hợp hỗ trợ” trong trang quản trị — cùng chỗ dùng để cài LiveChat hoặc Tawk.to. Dán mã vào đó.','bạn, nếu có quyền truy cập back office; nếu không, nhà vận hành hoặc đội kỹ thuật của nền tảng.'],
   ['Nhận diện người chơi','Để nhân viên thấy ID, tên hoặc tên đăng nhập của người chơi, trang web phải gửi dữ liệu đó cho widget. Để xem số dư, nạp hoặc rút tiền ngay trong hệ thống CSKH, nền tảng cần có API và cấp quyền truy cập.','đội kỹ thuật của nền tảng.']],
  code:'Mã mẫu cho từng trang',copy:'Sao chép',copied:'Đã sao chép',codeNote:'sac.example.com chỉ là ví dụ. Địa chỉ thật sẽ có sau bước 1.',
  st:'Tình trạng hiện tại',ready:'Đã xong',readyL:['Bản thử hệ thống CSKH: đăng nhập, phân quyền, line 7987 và 8557','Phân chat tự động, chuyển chat, script, tệp đính kèm'],
  we:'Chúng tôi làm tiếp',weL:['Máy chủ có cơ sở dữ liệu và chat thời gian thực','Widget chat cho hai trang web'],
  you:'Phụ thuộc vào bạn',youL:['Hosting và tên miền','Quyền vào back office của 7987.com và 8557.com, hoặc liên hệ đội kỹ thuật của họ'],
  simT:'Thử mô phỏng',simD:'Một trang game giả lập có bong bóng chat. Mở trong tab mới, nhắn tin như người chơi và trả lời trong CSKH.',simB:'Mở trang',ask:'Để tiếp tục: kiểm tra xem trang quản trị của 7987.com và 8557.com có mục để dán mã live chat hoặc script tùy chỉnh không.'},
 ur:{tab:'Roman Urdu',lang:'ur-Latn',title:'Help desk ko gaming site se jorna',intro:'7987.com ya 8557.com par player yahan agent tak kaise pohanchta hai, aur har party ko kya karna hai.',
  flow:['7987.com par player','Chat widget','Help desk server','Line 7987 ka agent'],step:'Qadam',who:'Kaun karega',opt:'optional',
  steps:[
   ['Help desk ko asli server par lagayen','Abhi yeh sirf browser ke andar chalta hai. Website se players lene ke liye isay database aur real-time connection wale server par host karna zaroori hai, apne address par jaise sac.example.com.','server ka code hum likhenge; hosting (VPS, Railway, Render…) aur domain aap lenge.'],
   ['Site par chat widget lagayen','Yeh screen ke kone mein chat ka bubble hai. Site par ek chhota sa code lagaya jata hai; data-linha batata hai ke player kis line se aaya: 7987.com ke liye 7987, 8557.com ke liye 8557.','widget hum banayenge.'],
   ['Platform ke back office mein code install karen','Gaming platforms ke admin panel mein aam tor par “live chat code”, “custom script” ya “support integration” jaisa field hota hai — wahi jagah jahan LiveChat ya Tawk.to lagaya jata hai. Code wahan paste karen.','aap, agar aap ke paas back office access hai; warna platform ka operator ya tech team.'],
   ['Player ki pehchan','Agent ko player ki ID, naam ya login dikhane ke liye site ko yeh data widget ko bhejna hoga. Help desk ke andar balance, deposit ya withdrawal dekhne ke liye platform ke paas API honi chahiye aur us ka access dena hoga.','platform ki tech team.']],
  code:'Har site ke liye misali code',copy:'Copy karen',copied:'Copy ho gaya',codeNote:'sac.example.com sirf misal hai. Asli address qadam 1 ke baad milega.',
  st:'Abhi hum kahan hain',ready:'Tayyar',readyL:['Help desk ka prototype: login, roles, line 7987 aur 8557','Automatic routing, transfer, scripts, attachments'],
  we:'Agla kaam hamara',weL:['Database aur real-time chat wala server','Dono sites ke liye chat widget'],
  you:'Aap par munhasir',youL:['Hosting aur domain','7987.com aur 8557.com ke back office ka access, ya un ki tech team se rabta'],
  simT:'Simulation azmaen',simD:'Chat bubble ke sath ek farzi gaming site. Naye tab mein kholen, player ban kar message karen aur help desk mein jawab den.',simB:'Site kholen',ask:'Aage barhne ke liye: check karen ke 7987.com aur 8557.com ke admin panel mein chat code ya custom script paste karne ka field hai ya nahin.'},
 en:{tab:'English',lang:'en',title:'Connect the help desk to a gaming site',intro:'How a player on 7987.com or 8557.com reaches an agent here, and what each party has to do.',
  flow:['Player on 7987.com','Chat widget','Help desk server','Agent on line 7987'],step:'Step',who:'Who does it',opt:'optional',
  steps:[
   ['Put the help desk on a real server','Today it runs only inside the browser. To receive players from a website, it must be hosted on a server with a database and a real-time connection, at its own address such as sac.example.com.','we write the server code; you get the hosting (VPS, Railway, Render…) and the domain.'],
   ['Add the chat widget to the site','This is the chat bubble in the corner of the screen. A small piece of code goes on the site; data-linha tells which line the player came from: 7987.com uses 7987, 8557.com uses 8557.','we build the widget.'],
   ['Install the code in the platform’s back office','Gaming platforms usually have a field such as “live chat code”, “custom script” or “support integration” in the admin panel — the same place used to install LiveChat or Tawk.to. Paste the code there.','you, if you have back-office access; otherwise the platform operator or its tech team.'],
   ['Identify the player','For agents to see the player’s ID, name or login, the site must send that data to the widget. To check balance, deposits or withdrawals inside the help desk, the platform needs an API and must grant access to it.','the platform’s tech team.']],
  code:'Example code for each site',copy:'Copy',copied:'Copied',codeNote:'sac.example.com is only an example. The real address comes after step 1.',
  st:'Where we are',ready:'Ready',readyL:['Help desk prototype: logins, roles, lines 7987 and 8557','Automatic routing, transfers, scripts, attachments'],
  we:'We build next',weL:['Server with database and real-time chat','Chat widget for both sites'],
  you:'Depends on you',youL:['Hosting and domain','Back-office access to 7987.com and 8557.com, or contact with their tech team'],
  simT:'Try the simulation',simD:'A fictional gaming site with the chat bubble. Open it in a new tab, write as a player and reply in the help desk.',simB:'Open site',ask:'To continue: check whether the admin panel of 7987.com and 8557.com has a field to paste live chat code or a custom script.'},
 zh:{tab:'中文',lang:'zh-Hans',title:'将客服系统接入游戏网站',intro:'7987.com 或 8557.com 的玩家如何联系到这里的客服，以及各方需要做什么。',
  flow:['7987.com 的玩家','聊天组件','客服服务器','7987 线路客服'],step:'步骤',who:'负责方',opt:'可选',
  steps:[
   ['将客服系统部署到正式服务器','目前系统只在浏览器中运行。要接收来自网站的玩家，系统必须部署在带有数据库和实时连接的服务器上，并使用独立地址，例如 sac.example.com。','服务器代码由我们编写；主机（VPS、Railway、Render 等）和域名由您购买。'],
   ['在网站上添加聊天组件','即网页角落的聊天气泡。在网站中放入一小段代码；data-linha 表示玩家来自哪条线路：7987.com 使用 7987，8557.com 使用 8557。','组件由我们开发。'],
   ['在平台后台安装代码','游戏平台的管理后台通常有“在线客服代码”、“自定义脚本”或“客服集成”之类的字段——也就是安装 LiveChat 或 Tawk.to 的地方。把代码粘贴到那里。','如果您有后台权限，由您操作；否则由平台运营方或其技术团队操作。'],
   ['识别玩家','要让客服看到玩家的 ID、姓名或登录名，网站需要把这些数据发送给聊天组件。要在客服系统中查询余额、充值或提现，平台需要提供 API 并开放权限。','平台技术团队。']],
  code:'各网站的示例代码',copy:'复制',copied:'已复制',codeNote:'sac.example.com 只是示例，正式地址在完成步骤 1 后确定。',
  st:'当前进度',ready:'已完成',readyL:['客服系统原型：登录、权限、7987 和 8557 线路','自动分配、转接、快捷话术、文件上传'],
  we:'我们接下来做',weL:['带数据库和实时聊天的服务器','两个网站的聊天组件'],
  you:'需要您提供',youL:['主机和域名','7987.com 和 8557.com 的后台权限，或联系其技术团队'],
  simT:'体验模拟',simD:'一个带聊天气泡的虚构游戏网站。在新标签页打开，以玩家身份发消息，然后在客服系统中回复。',simB:'打开网站',ask:'下一步：请确认 7987.com 和 8557.com 的管理后台是否有可粘贴在线客服代码或自定义脚本的字段。'}
};